import xml.etree.ElementTree as ET

from seed.twiml.messaging_response import Message, MessagingResponse
from seed.twiml.voice_response import Dial, Gather, Prompt, Say, SsmlEmphasis, VoiceResponse


def canonical(xml: str) -> str:
    return ET.canonicalize(xml, strip_text=True)


def test_message_media() -> None:
    response = MessagingResponse()
    message = Message(to="+15558675310", from_="+15017122661")
    message.body('Hello, "World" <3')
    message.media("https://demo.twilio.com/owl.png")
    response.append(message)
    response.redirect("https://example.com/fallback")

    assert canonical(str(response)) == canonical(
        '<?xml version="1.0" encoding="UTF-8"?>\n<Response>\n    <Message to="+15558675310" from="+15017122661">\n        <Body>Hello, "World" &lt;3</Body>\n        <Media>https://demo.twilio.com/owl.png</Media>\n    </Message>\n    <Redirect>https://example.com/fallback</Redirect>\n</Response>\n'
    )


def test_message_simple() -> None:
    response = MessagingResponse()
    response.message("Hello from Fern")

    assert canonical(str(response)) == canonical("<Response>\n    <Message>Hello from Fern</Message>\n</Response>\n")


def test_dial_number() -> None:
    response = VoiceResponse()
    dial = Dial(caller_id="+15551112222", hangup_on_star=True)
    dial.number(
        "+15558675310", status_callback_event=["initiated", "ringing"], byoc="BY1234567890abcdef1234567890abcdef"
    )
    response.append(dial)

    assert canonical(str(response)) == canonical(
        '<Response>\n    <Dial callerId="+15551112222" hangupOnStar="true">\n        <Number statusCallbackEvent="initiated ringing" byoc="BY1234567890abcdef1234567890abcdef">+15558675310</Number>\n    </Dial>\n</Response>\n'
    )


def test_gather_prompt() -> None:
    response = VoiceResponse()
    gather = Gather(input=["dtmf", "speech"], num_digits=4)
    gather.say("Please enter your card number.")
    prompt = Prompt(for_="payment-card-number", attempt=[1, 2])
    prompt.say("Card number & expiry, please.", voice="alice")
    prompt.pause(length=1)
    gather.append(prompt)
    response.append(gather)
    response.redirect("https://example.com/next?step=2&retry=true", method="POST")

    assert canonical(str(response)) == canonical(
        '<Response>\n    <Gather input="dtmf speech" numDigits="4">\n        <Say>Please enter your card number.</Say>\n        <Prompt for="payment-card-number" attempt="1 2">\n            <Say voice="alice">Card number &amp; expiry, please.</Say>\n            <Pause length="1"/>\n        </Prompt>\n    </Gather>\n    <Redirect method="POST">https://example.com/next?step=2&amp;retry=true</Redirect>\n</Response>\n'
    )


def test_say_hello() -> None:
    response = VoiceResponse()
    response.say("Hello!", voice="woman", loop=2)

    assert canonical(str(response)) == canonical(
        '<?xml version="1.0" encoding="UTF-8"?>\n<Response>\n    <Say voice="woman" loop="2">Hello!</Say>\n</Response>\n'
    )


def test_ssml_mixed() -> None:
    response = VoiceResponse()
    say = Say("Hello ")
    ssml_emphasis = SsmlEmphasis("world", level="strong")
    ssml_emphasis.break_(strength="x-weak")
    ssml_emphasis.add_text("again")
    say.append(ssml_emphasis)
    say.add_text(", bye")
    response.append(say)

    assert canonical(str(response)) == canonical(
        '<Response>\n    <Say>Hello <emphasis level="strong">world<break strength="x-weak"/>again</emphasis>, bye</Say>\n</Response>\n'
    )
